Test structure with Convex mocking:

```typescript
import { describe, it, expect, vi } from 'vitest';

// Mock the Convex context
const mockCtx = (identity: { subject: string } | null) => {
  const authUser = identity ? { _id: identity.subject, userId: identity.subject } : null;

  // Mock the Query object returned by ctx.db.query().withIndex()...
  const mockQueryResults = {
    first: vi.fn().mockResolvedValue(authUser),
  };

  const mockIndexQuery = vi.fn().mockImplementation((indexName: string) => {
    if (indexName === "authId" && identity) {
      return mockQueryResults;
    }
    return { first: vi.fn().mockResolvedValue(null) };
  });

  const mockQuery = vi.fn().mockImplementation((tableName: string) => {
    if (tableName === "users") {
      return {
        withIndex: mockIndexQuery,
      };
    }
    return { withIndex: vi.fn().mockReturnValue({ first: vi.fn().mockResolvedValue(null) }) };
  });

  return {
    auth: {
      getUserIdentity: vi.fn().mockResolvedValue(identity),
    },
    // Mock runQuery as it is likely called by safeGetAuthUser
    runQuery: vi.fn().mockResolvedValue(authUser),
    db: {
      query: mockQuery,
    },
    // Mock other properties required by AuthContextWithDb if they cause type errors
    storage: {}, // Mock storage
    scheduler: {}, // Mock scheduler
    runMutation: vi.fn(), // Mock runMutation
    runAction: vi.fn(), // Mock runAction
    // Add other properties if needed based on type errors
  } as unknown as AuthContextWithDb; // Cast to AuthContextWithDb
};

describe('authHelpers', () => {
  describe('getAuthUserId', () => {
    it('returns userId when authenticated', async () => {
      const ctx = mockCtx({ subject: 'user-123' });
      const result = await getAuthUserId(ctx);
      expect(result).toBe('user-123');
    });

    it('returns null when not authenticated', async () => {
      const ctx = mockCtx(null);
      const result = await getAuthUserId(ctx);
      expect(result).toBeNull();
    });
  });

  describe('requireAuth', () => {
    it('throws ConvexError when not authenticated', async () => {
      const ctx = mockCtx(null);
      // Assuming requireAuth uses throw new Error(...) and not a specific ConvexError
      await expect(requireAuth(ctx)).rejects.toThrow('Authentication required');
    });

    it('returns userId when authenticated', async () => {
      const ctx = mockCtx({ subject: 'user-456' });
      const result = await requireAuth(ctx);
      expect(result).toBe('user-456');
    });
  });
});
